entries[1213479] = { ["name"] = "Lightning Shield", ["text"] = "5 Mana 30 yd range\nInstant 10 sec cooldown\nSurrounds the caster with 3 balls of lightning that have 50% chance of striking melee or ranged attackers for 2 damage. Each time the lightning shield strikes, a ball of lightning dissipates. Thus, the shield expires after 10 min. or after it has struck 3 times.\n(Proc chance: 50%)" }
entries[1213480] = { ["name"] = "Earthbind Totem", ["text"] = "40 Mana\nInstant\nTools: Earth Totem\nSummons an Earthbind Totem that lasts 45 sec. and periodically reduces the movement speed of nearby enemies to 50% of normal." }
entries[1213481] = { ["name"] = "Razorspike Headcage", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (15), Obsidian-Infused Thorium Bar (3), Enchanted Leather (4), Wicked Claw (10), Monstrous Silithid Chitin (4)\nRazorspike Headcage\nBinds when equipped\nHead Plate\n722 Armor\n+14 Strength\n+40 Stamina\nDurability 100 / 100\n60\nEquip: When struck in combat inflicts 100 Nature damage to the attacker. Causes twice as much threat as damage dealt.\nEquip: Increased Defense +9." }
entries[1213482] = { ["name"] = "Flame Shock", ["text"] = "110 Mana 20 yd range\nInstant\nInstantly burns an enemy, then inflicts additional Fire damage every 3 sec. for 12 sec." }
entries[1213483] = { ["name"] = "Plans: Razorspike Shoulderplates", ["text"] = "100 yd range\n3 sec cast\nTeaches you how to make Razorspike Shoulderplates." }
