entries[1213490] = { ["name"] = "Razorspike Battleplate", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (20), Obsidian-Infused Thorium Bar (4), Enchanted Leather (4), Wicked Claw (10), Monstrous Silithid Chitin (8)\nRazorspike Battleplate\nBinds when equipped\nChest Plate\n889 Armor\n+12 Strength\n+40 Stamina\nDurability 165 / 165\n60\nEquip: When struck in combat inflicts 100 Nature damage to the attacker. Causes twice as much threat as damage dealt.\nEquip: Increased Defense +10." }
entries[1213491] = { ["name"] = "Plans: Obsidian Reaver", ["text"] = "100 yd range\n3 sec cast\nTeaches you how to make Obsidian Reaver." }
entries[1213492] = { ["name"] = "Obsidian Reaver", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (40), Obsidian-Infused Thorium Bar (10), Enchanted Leather (8), Obsidian Grinding Stone (6), Alabaster Idol (4), Idol of War (2)\nObsidian Reaver\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)Two-Hand Axe\n203 - 340 Damage Speed 3.70\n(73.38 damage per second)\n+40 Strength\n+30 Stamina\nDurability 120 / 120\n60\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)" }
entries[1213496] = { ["name"] = "Plans: Obsidian Champion", ["text"] = "100 yd range\n3 sec cast\nTeaches you how to make Obsidian Champion." }
entries[1213498] = { ["name"] = "Obsidian Champion", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (40), Obsidian-Infused Thorium Bar (10), Enchanted Leather (8), Obsidian Grinding Stone (6), Vermillion Idol (4), Idol of Life (2)\nObsidian Champion\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)Two-Hand Sword\n117 - 176 Damage Speed 2.00\n(73.25 damage per second)\nDurability 120 / 120\n60\nChance on hit: Heal self for 270 to 450 and Increases Strength by 120 for 30 sec.\nChance on hit: Increases damage done by 20 and attack speed by 5% for 15 sec.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)" }
entries[1213499] = { ["name"] = "Plans: Obsidian Destroyer", ["text"] = "100 yd range\n3 sec cast\nTeaches you how to make Obsidian Destroyer." }
entries[1213500] = { ["name"] = "Obsidian Destroyer", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (40), Obsidian-Infused Thorium Bar (10), Obsidian Grinding Stone (8), Alabaster Idol (4), Vermillion Idol (4), Idol of Night (2)\nObsidian Destroyer\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)Two-Hand Mace\n117 - 176 Damage Speed 2.00\n(73.25 damage per second)\n+40 Strength\nDurability 120 / 120\n60\nEquip: +260 Attack Power in Cat, Bear, and Dire Bear forms only.\nChance on hit: Stuns target for 3 sec.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)" }
entries[1213501] = { ["name"] = "Plans: Obsidian Stormhammer", ["text"] = "100 yd range\n3 sec cast\nTeaches you how to make Obsidian Stormhammer." }
entries[1213502] = { ["name"] = "Obsidian Stormhammer", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (30), Obsidian-Infused Thorium Bar (8), Enchanted Leather (5), Obsidian Grinding Stone (6), Obsidian Idol (3), Idol of Rebirth (2)\nObsidian Stormhammer\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)Main Hand Mace\n49 - 117 Damage Speed 2.00\n(41.50 damage per second)\n+10 Stamina\n+8 Intellect\nDurability 105 / 105\n60\nChance on hit: Blasts up to 3 targets for 105 to 145 Nature damage.\nEquip: Increases damage and healing done by magical spells and effects by up to 60.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)" }
entries[1213503] = { ["name"] = "Plans: Obsidian Sageblade", ["text"] = "100 yd range\n3 sec cast\nTeaches you how to make Obsidian Sageblade." }
entries[1213504] = { ["name"] = "Obsidian Sageblade", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (30), Obsidian-Infused Thorium Bar (8), Nexus Crystal (3), Obsidian Grinding Stone (3), Obsidian Idol (3), Idol of the Sage (2)\nObsidian Sageblade\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)Main Hand Sword\n37 - 88 Damage Speed 1.50\n(41.67 damage per second)\n+14 Stamina\n+12 Intellect\nDurability 105 / 105\n60\nEquip: Increases damage and healing done by magical spells and effects by up to 60.\nEquip: Decreases the magical resistances of your spell targets by 20.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)" }
entries[1213505] = { ["name"] = "Plans: Obsidian Defender", ["text"] = "100 yd range\n3 sec cast\nTeaches you how to make Obsidian Defender." }
entries[1213506] = { ["name"] = "Obsidian Defender", ["text"] = "1 min cast\nTools: Blacksmith Hammer\nReagents:\nArcanite Bar (30), Obsidian-Infused Thorium Bar (8), Obsidian Grinding Stone (6), Vermillion Idol (3), Obsidian Idol (3), Idol of the Sun (2)\nObsidian Defender\nBinds when equipped\nUnique-Equipped: Obsidian Weapon (1)Main Hand Axe\n106 - 198 Damage Speed 2.70\n(56.30 damage per second)\n+11 Stamina\nDurability 105 / 105\n60\nEquip: Improves your chance to hit with all spells and attacks by 1%.\nEquip: Increased Defense +9.\nEquip: Chance on direct spell damage or melee attack to deal 325 to 500 Fire damage to your target. Deals extra damage to Silithid creatures in Silithus on almost every hit. (2.1s cooldown)" }
